begin;
set local search_path=public,extensions;
select no_plan();
create temporary table snapshot_fixture(id uuid,coop uuid);
create temporary table snapshot_cursor(position text);
insert into snapshot_cursor select coalesce(max(revision),0)::text from private.snapshot_change;
insert into snapshot_fixture values(gen_random_uuid(),'10000000-0000-4000-8000-000000000001'),(gen_random_uuid(),'10000000-0000-4000-8000-000000000002');
insert into public.supplier(id,cooperative_id,name,type,status) select id,coop,'Incremental fixture','dairy','approved' from snapshot_fixture;
grant select on snapshot_fixture,snapshot_cursor to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select ok(not has_table_privilege('authenticated','private.snapshot_change','select'),'Key journal is not directly readable');
select ok(public.snapshot_checkpoint() ? 'epoch' and public.snapshot_checkpoint() ? 'access','Checkpoint identifies replica epoch and access scope');
select ok(exists(select 1 from jsonb_array_elements(public.snapshot_changes('1:1:','1:9223372036854775807:',(select position from snapshot_cursor),500)->'changes') change where change->>'table'='supplier' and change->>'key'=(select id::text from snapshot_fixture where coop='10000000-0000-4000-8000-000000000001') and change->'row'->>'name'='Incremental fixture'),'Incremental records are returned under caller RLS');
select ok(not exists(select 1 from jsonb_array_elements(public.snapshot_changes('1:1:','1:9223372036854775807:',(select position from snapshot_cursor),500)->'changes') change where change->>'key'=(select id::text from snapshot_fixture where coop='10000000-0000-4000-8000-000000000002')),'Other cooperative changes do not leak');
select ok(not(public.snapshot_changes('1:1:','1:9223372036854775807:',(select position from snapshot_cursor),1)->>'complete')::boolean,'Page boundary reports additional changes');
select is(jsonb_array_length(public.snapshot_changes('1:1:','1:9223372036854775807:',(select position from snapshot_cursor),1)->'changes'),1,'Snapshot pages respect their requested limit');
select throws_ok($$select public.snapshot_changes('1:1:','1:9223372036854775807:','-1',500)$$,'P0001','Invalid snapshot cursor','Negative cursors are rejected');
select is((select count(*) from public.snapshot_balances(array['60000000-0000-4000-8000-000000000001'::uuid])),1::bigint,'Changed-lot balance query returns only requested visible stock');
select ok(not has_function_privilege('anon','public.snapshot_changes(text,text,text,integer)','execute'),'Anonymous users cannot download incremental snapshots');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000007","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.snapshot_changes('1:1:','1:9223372036854775807:','0',500)$$,'P0001','Snapshot permission required','Donor raw incremental records remain blocked');
reset role;
delete from public.supplier where id in(select id from snapshot_fixture);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select ok(exists(select 1 from jsonb_array_elements(public.snapshot_changes('1:1:','1:9223372036854775807:',(select position from snapshot_cursor),500)->'changes') change where change->>'table'='supplier' and change->>'key'=(select id::text from snapshot_fixture where coop='10000000-0000-4000-8000-000000000001') and change->'row'='null'::jsonb),'Deletion is conveyed without a stale record body');
select * from finish();
rollback;
